import { useState } from 'react';
import './application-shell.css';

export function ApplicationShell() {
  const [inspectorOpen, setInspectorOpen] = useState(true);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  return (
    <div className="app-shell">
      <header className="app-toolbar">
        <button aria-label="Toggle navigation" aria-expanded={sidebarOpen} onClick={() => setSidebarOpen(!sidebarOpen)}>☰</button>
        <strong>Atlas</strong><span className="toolbar-spacer" />
        <button aria-pressed={inspectorOpen} onClick={() => setInspectorOpen(!inspectorOpen)}>Inspector</button>
      </header>
      <div className="app-body">
        <nav className={sidebarOpen ? 'sidebar is-open' : 'sidebar'} aria-label="Workspace navigation">
          <h2>Workspace</h2><a href="#inbox">Inbox</a><a href="#projects">Projects</a>
          <h2>Views</h2><a href="#today">Today</a><a href="#archive">Archive</a>
        </nav>
        <main className="workspace" tabIndex={-1}><h1>Inbox</h1><p>Workspace content scrolls independently from the application toolbar.</p></main>
        {inspectorOpen && <aside className="inspector" aria-label="Inspector"><h2>Details</h2><p>Select an item to inspect it.</p></aside>}
      </div>
    </div>
  );
}
